// Canonical v1 measurement definitions. The server replaces client text with these values.
export const BENCHMARK_METHODOLOGY=Object.freeze({fps:'render submission cadence after the game FPS cap, not proof of displayed frames',average_fps:'1000 * frame count / sum of active rendered frame intervals',percentiles:'estimates from fixed histograms: 0.125 ms bins below 64 ms, 0.5 ms below 256 ms, 2 ms below 512 ms, powers of two above',low_1_percent:'1000 / estimated mean of the slowest ceil(1% of frames), using bucket means at the boundary',cpu:'measured JS main-thread wall time for update, events, HUD and render submission; not utilisation or GPU time',gpu:'measured asynchronous existing WebGL2 timer queries every 12 rendered frames; disjoint results rejected',memory:'JS heap and owned texture bytes are estimates when exposed; process memory, VRAM, battery and temperature unavailable',raw:'uniform reservoir of rendered frame observations; independent benchmark RNG, no simulation RNG changes',conditions:'overlapping steady-play labels; shots: 1 second, explosions: 2 seconds, indoors/population sampled once per second',spike:'frame interval > max(50 ms, twice the configured frame budget)',stutter:'frame interval > 1.5 times the configured frame budget',warmup:'first 15 active seconds of each match; background/menu/loading excluded; resume primes the frame clock',histogram:'sparse rows [bucket index, frame count, sum_ms]; see benchmark-stats.js for bin bounds'});
